void main() {
  print('=== Dart Sound Null Safety & Late Keyword ===\n');

  demonstrateBasicNullSafety();
  demonstrateLateInitialization();
  demonstrateLateVsNullable();
}

void demonstrateBasicNullSafety() {
  print('1. Sound Null Safety Basics:');
  print('----------------------------');

  // Non-nullable types cannot be null
  String name = 'Alice';
  int age = 25;

  // Nullable types use ? and can be null
  String? nickname;  // null by default
  int? score = null;

  print('Name: $name (length: ${name.length})');
  print('Nickname: ${nickname ?? 'No nickname'} (length: ${nickname?.length ?? 0})');

  // Safe navigation and null-aware operators
  print('Score doubled: ${score != null ? score * 2 : 'No score'}');
  print('Score with null-aware: ${(score ?? 0) * 2}\n');
}

void demonstrateLateInitialization() {
  print('2. Late Keyword Examples:');
  print('-------------------------');

  // Late variable - defers initialization
  late String heavyComputation;
  print('Late variable declared but not initialized yet...');

  // Initialize when needed
  heavyComputation = performHeavyComputation();
  print('Late variable initialized: $heavyComputation');

  // Late final - can only be set once
  late final String appConfig;
  appConfig = 'production';
  // appConfig = 'development'; // Would cause error
  print('App config: $appConfig');

  // Late with initializer (lazy evaluation)
  late final DateTime lazyTime = DateTime.now();
  print('First access to lazy time: $lazyTime');

  // Demonstrate class usage
  var service = ApiService();
  print('API Service initialized');
  service.makeRequest();

  print('');
}

void demonstrateLateVsNullable() {
  print('3. When to Use Late vs Nullable:');
  print('--------------------------------');

  // Use LATE when:
  // - You guarantee the value will be set before use
  // - You want to defer expensive initialization
  // - The value is required but can't be set at declaration

  var fileProcessor = FileProcessor();
  fileProcessor.initialize();
  print(fileProcessor.processFile('data.txt'));

  // Use NULLABLE when:
  // - The value might legitimately be absent
  // - You want to represent "no value" as a valid state

  var userProfile = UserProfile();
  print('Avatar URL: ${userProfile.getAvatarUrl()}');
  userProfile.setAvatar('https://example.com/avatar.jpg');
  print('Avatar URL after setting: ${userProfile.getAvatarUrl()}');
}

String performHeavyComputation() {
  // Simulate expensive operation
  return 'Heavy computation result';
}

class ApiService {
  late String baseUrl;
  late Map<String, String> headers;

  ApiService() {
    print('  ApiService constructor called');
    // Initialize late variables
    baseUrl = 'https://api.example.com';
    headers = {'Content-Type': 'application/json'};
  }

  void makeRequest() {
    print('  Making request to: $baseUrl');
    print('  Headers: $headers');
  }
}

// Example: Use late for guaranteed initialization
class FileProcessor {
  late String workingDirectory;
  late bool isInitialized;

  void initialize() {
    workingDirectory = '/tmp/processing';
    isInitialized = true;
  }

  String processFile(String filename) {
    if (!isInitialized) {
      throw StateError('FileProcessor not initialized');
    }
    return 'Processing $filename in $workingDirectory';
  }
}

// Example: Use nullable for optional values
class UserProfile {
  String? avatarUrl;  // Optional - user might not have an avatar
  String? bio;        // Optional - user might not have a bio

  String getAvatarUrl() {
    return avatarUrl ?? 'default-avatar.png';
  }

  void setAvatar(String url) {
    avatarUrl = url;
  }
}

// Common Null Safety Patterns and Best Practices

void main() {
  print('=== Null Safety Patterns & Best Practices ===\n');

  demonstrateNullAwareOperators();
  demonstrateLateBestPractices();
  demonstrateCommonPatterns();
}

void demonstrateNullAwareOperators() {
  print('1. Null-Aware Operators:');
  print('------------------------');

  String? name;
  List<String>? items;

  // Null-aware access (?.)
  print('Name length: ${name?.length}'); // Returns null if name is null

  // Null coalescing (??)
  print('Display name: ${name ?? 'Anonymous'}'); // Use default if null

  // Null-aware assignment (??=)
  name ??= 'Default Name'; // Assign only if null
  print('After ??= assignment: $name');

  // Null-aware spread (...?)
  List<String> finalList = [
    'Always present',
    ...?items, // Only spread if items is not null
  ];
  print('Final list: $finalList');

  // Null assertion (!) - use sparingly!
  String? definitelyNotNull = 'Hello';
  print('Forced access: ${definitelyNotNull!.toUpperCase()}');

  print('');
}

void demonstrateLateBestPractices() {
  print('2. Late Keyword Best Practices:');
  print('-------------------------------');

  // ✅ Good: Late for dependency injection
  var controller = UserController();
  controller.initialize();
  print(controller.getUsers());

  // ✅ Good: Late final for expensive one-time computation
  var calculator = ExpensiveCalculator();
  print('First calculation: ${calculator.result}');
  print('Second calculation: ${calculator.result}'); // Uses cached result

  // ✅ Good: Late for two-phase initialization
  var database = Database();
  database.connect();
  database.setupTables();
  print(database.query('SELECT COUNT(*) FROM users'));

  print('');
}

void demonstrateCommonPatterns() {
  print('3. Common Patterns:');
  print('------------------');

  // Pattern 1: Nullable with default
  var settings = AppSettings();
  print('Theme: ${settings.getTheme()}');
  print('Font size: ${settings.getFontSize()}');

  // Pattern 2: Late initialization with validation
  var validator = FormValidator();
  validator.configure();
  print('Email valid: ${validator.isValidEmail('test@example.com')}');

  // Pattern 3: Nullable chain operations
  var user = User('John', null);
  var displayInfo = user.profile
      ?.avatar
      ?.url
      ?? 'No avatar';
  print('Avatar: $displayInfo');

  print('');
}

// Dependency injection pattern with late
class UserController {
  late UserService _userService;
  late Logger _logger;

  void initialize() {
    _userService = UserService();
    _logger = Logger();
  }

  String getUsers() {
    _logger.log('Fetching users');
    return _userService.fetchUsers();
  }
}

class UserService {
  String fetchUsers() => 'User data from service';
}

class Logger {
  void log(String message) => print('LOG: $message');
}

// Lazy initialization pattern
class ExpensiveCalculator {
  late final double result = _performCalculation();

  double _performCalculation() {
    print('  Performing expensive calculation...');
    // Simulate expensive computation
    return 42.0 * 1.618; // Golden ratio calculation
  }
}

// Two-phase initialization pattern
class Database {
  late String connectionString;
  late bool isConnected;
  late Map<String, String> tables;

  void connect() {
    connectionString = 'sqlite://memory';
    isConnected = true;
  }

  void setupTables() {
    if (!isConnected) throw StateError('Not connected');
    tables = {'users': 'CREATE TABLE users...', 'posts': 'CREATE TABLE posts...'};
  }

  String query(String sql) {
    if (!isConnected) throw StateError('Not connected');
    return 'Query result for: $sql';
  }
}

// Nullable with defaults pattern
class AppSettings {
  String? _theme;
  int? _fontSize;

  String getTheme() => _theme ?? 'light';
  int getFontSize() => _fontSize ?? 14;

  void setTheme(String theme) => _theme = theme;
  void setFontSize(int size) => _fontSize = size;
}

// Late with validation pattern
class FormValidator {
  late RegExp _emailRegex;
  late List<String> _bannedDomains;

  void configure() {
    _emailRegex = RegExp(r'^[\w-\.]+@([\w-]+\.)+[\w-]{2,4}$');
    _bannedDomains = ['spam.com', 'fake.org'];
  }

  bool isValidEmail(String email) {
    if (!_emailRegex.hasMatch(email)) return false;

    String domain = email.split('@').last;
    return !_bannedDomains.contains(domain);
  }
}

// Nullable chaining pattern
class User {
  final String name;
  final UserProfile? profile;

  User(this.name, this.profile);
}

class UserProfile {
  final Avatar? avatar;
  UserProfile(this.avatar);
}

class Avatar {
  final String url;
  Avatar(this.url);
}
